def whois(cls, whois_server, domain=None, timeout=None):
    # If no domain is provided, use the domain or IP we are currently testing
    if domain is None:
        domain = PyFunceble.INTERN["to_test"]
    # If no timeout is provided, use the timeout from the configuration
    if timeout is None:
        timeout = PyFunceble.CONFIGURATION["seconds_before_http_timeout"]
    # If a whois server is provided, initiate a socket
    if whois_server:
        req = PyFunceble.socket.socket(PyFunceble.socket.AF_INET, PyFunceble.socket.SOCK_STREAM)
        # Set the timeout if it's a multiple of 3
        if timeout % 3 == 0:
            req.settimeout(timeout)
        else:
            req.settimeout(3)
        try:
            # Connect to the whois server at port 43
            req.connect((whois_server, 43))
        except PyFunceble.socket.error:
            # Return None if an error occurs
            return None
        # Send the domain to the server
        req.send((domain + "\r\n").encode())
        # Initialize a bytes variable to store the response
        response = b""
        while True:
            # Receive data in a buffer of 4096 bytes
            data = req.recv(4096)
            if not data:
                # Break the loop if no data is received
                break
            # Append data to the response
            response += data
        # Close the connection
        req.close()
        try:
            # Decode and return the response
            return response.decode()
        except UnicodeDecodeError:
            # Decode the response and replace non-utf-8 characters
            return response.decode("utf-8", "replace")
    # Return None if no whois server is provided
    return None

